class IntraOptionPolicy(nn.Module):
    def __init__(self, state_dim, n_options, n_actions):
        super().__init__()
        self.n_options = n_options
        self.head = nn.Linear(state_dim, n_options * n_actions)
        self.n_actions = n_actions

    def forward(self, state):
        logits = self.head(state).view(-1, self.n_options, self.n_actions)
        return torch.distributions.Categorical(logits=logits)


def intra_option_loss(dist, option, action, option_value, mask=None):
    logits = dist.logits
    if mask is not None:
        # mask 为 0 的动作概率置零后重新归一化
        logits = logits.masked_fill(mask == 0, float('-inf'))
    dist = torch.distributions.Categorical(logits=logits)
    logp = dist.log_prob(action)
    return -(logp * option_value.detach()).mean()

import torch

def merge_task_vectors(base_sd, vectors, lambdas=None):
    # base_sd: 基座 state_dict; vectors: [{"state": sd, "name": str}, ...]
    lambdas = lambdas or [1.0 / len(vectors)] * len(vectors)
    out = {k: v.clone() for k, v in base_sd.items()}
    for w, vec in zip(lambdas, vectors):
        for k, v in vec["state"].items():
            if out[k].dtype.is_floating_point:
                out[k] = out[k] + w * (v - base_sd[k])   # base + sum lambda * tau
    return out


