import numpy as np
from collections import deque

def temporal_distance(goal, grid, blocked):
    # grid: (H, W); blocked: set of obstacles -> BFS 得到每格到目标的步数
    H, W = grid.shape
    dist = np.full((H, W), np.inf)
    dist[goal] = 0.0
    q = deque([goal])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in blocked:
                if dist[nr, nc] > dist[r, c] + 1:
                    dist[nr, nc] = dist[r, c] + 1
                    q.append((nr, nc))
    return dist   # phi(s, g) = dist[s]; 确定性环境下即时间距离


def fourier_features(x, B):
    # 随机傅里叶位置编码: 状态的替代表示
    proj = x @ B                     # B: (d, m) ~ N(0, sigma^2)
    return np.concatenate([np.sin(proj), np.cos(proj)], axis=-1)

