import numpy as np

def rank_actions(model, state, actions, H=5, gamma=0.99):
    """用 H 步想象轨迹的折扣回报给候选动作排序。"""
    scores = []
    for a in actions:
        s, total = state, 0.0
        for k in range(H):
            s, r = model.step(s, a)      # 世界模型前向一步
            total += (gamma ** k) * r
        scores.append(total)             # 目标超出行程时各动作分数几乎相同
    return np.argsort(-np.asarray(scores)), np.asarray(scores)

import torch, torch.nn as nn

class LoRALinear(nn.Module):
    def __init__(self, base: nn.Linear, r=8, alpha=16):
        super().__init__()
        self.base = base
        for p in self.base.parameters():
            p.requires_grad = False
        self.A = nn.Parameter(torch.randn(r, base.in_features) * 0.01)
        self.B = nn.Parameter(torch.zeros(base.out_features, r))
        self.scale = alpha / r

    def forward(self, x):
        return self.base(x) + self.scale * (x @ self.A.T @ self.B.T)

