def contract_net(tasks, agents, value, cost, capable, priority=None):
    # 贪心合同网：按任务优先级逐个选净效用最大且可行的智能体
    order = sorted(range(len(tasks)),
                   key=lambda j: -(priority[j] if priority else value[j]))
    assignment, load = {}, {i: 0 for i in agents}
    for j in order:
        best, best_u = None, float('-inf')
        for i in agents:
            if not capable(i, j):
                continue
            u = value[j] - cost(i, j, load[i])      # 负载会抬高实际代价
            if u > best_u:
                best, best_u = i, u
        if best is not None:
            assignment[j] = best
            load[best] += 1
    return assignment, load

