import math


def skill_score(pi_theta, dataset, skill):
    total = 0.0
    for x, y in dataset:
        p = pi_theta.logprob(y, prompt=x, skill=skill)
        total += math.log(max(p, 1e-12))
    return total / max(len(dataset), 1)


def pick_best(skills, dataset, pi_theta):
    return max(skills, key=lambda s: skill_score(pi_theta, dataset, s))

def reflective_loop(skill, dataset, pi_theta, edit_fn, rounds=4):
    history = []
    for k in range(rounds):
        failures = []
        for x, y in dataset:
            pred = pi_theta.generate(x, skill=skill)
            if pred.strip() != y.strip():
                failures.append((x, y, pred))
        history.append(len(failures))
        if not failures:
            break
        skill = edit_fn(skill, failures)
    return skill, history

import torch
import torch.nn.functional as F

@torch.no_grad()
def ema_update(student, target, decay=0.999):
    for ps, pt in zip(student.parameters(), target.parameters()):
        pt.mul_(decay).add_(ps.detach(), alpha=1.0 - decay)

def consistency_distill(student, target, x0, t_hi, t_lo, q_sample, distance=F.mse_loss):
    # q_sample 为扩散前向加噪：x_t = sqrt(a_t) * x0 + sqrt(1 - a_t) * eps
    x_hi = q_sample(x0, t_hi)
    x_lo = q_sample(x0, t_lo)
    pred_hi = student(x_hi, t_hi)
    with torch.no_grad():
        pred_lo = target(x_lo, t_lo)
    return distance(pred_hi, pred_lo)
